class _S extends State<W> {
  late final AnimationController _ctrl;
  StreamSubscription? _sub;

  @override
  void initState() {
    super.initState();                 // sempre per prima
    _ctrl = AnimationController(vsync: this, duration: kThemeAnimationDuration);
    _sub = stream.listen((_) => setState(() {}));
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final theme = Theme.of(context);   // qui sicuro, in initState no
  }

  @override
  void didUpdateWidget(W old) {
    super.didUpdateWidget(old);
    if (old.id != widget.id) reload(); // il genitore ha passato un id nuovo
  }

  @override
  void dispose() {
    _sub?.cancel();                    // tutto quello creato sopra
    _ctrl.dispose();
    super.dispose();                   // sempre per ultima
  }
}

